const PROJECT_STORAGE_KEY = "calltouch-generators-state-v2";
let saveProjectTimer = 0;

function scheduleProjectSave() {
  window.clearTimeout(saveProjectTimer);
  saveProjectTimer = window.setTimeout(saveProjectState, 250);
}

function saveProjectState() {
  try {
    const caseForm = {};
    elements.editorForm?.querySelectorAll("input, textarea, select").forEach((control) => {
      if (!control.id) return;
      caseForm[control.id] = control instanceof HTMLInputElement && (control.type === "checkbox" || control.type === "radio")
        ? control.checked
        : control.value;
    });
    const selectedBackground = elements.editorForm?.querySelector('input[name="background"]:checked')?.value;
    localStorage.setItem(PROJECT_STORAGE_KEY, JSON.stringify({ appState, caseForm, selectedBackground }));
  } catch (error) {
    console.warn("Не удалось сохранить настройки генератора.", error);
  }
}

function restoreProjectState() {
  try {
    const saved = JSON.parse(localStorage.getItem(PROJECT_STORAGE_KEY) || "null");
    if (!saved?.appState) return false;

    const defaults = createBannerDefaults();
    Object.assign(appState.ui, saved.appState.ui || {});
    // Положение рабочей области не восстанавливаем: оно зависит от размера окна.
    appState.ui.caseCanvas = { zoom: 1, panX: 0, panY: 0 };
    appState.ui.bannerCanvas = { zoom: 1, panX: 0, panY: 0 };
    Object.assign(appState.caseCard, saved.appState.caseCard || {});
    appState.banners = {
      ...defaults,
      ...saved.appState.banners,
      content: { ...defaults.content, ...saved.appState.banners?.content },
      branding: { ...defaults.branding, ...saved.appState.banners?.branding },
      visual: { ...defaults.visual, ...saved.appState.banners?.visual },
      layout: { ...defaults.layout, ...saved.appState.banners?.layout },
      compliance: { ...defaults.compliance, ...saved.appState.banners?.compliance },
      animation: { ...defaults.animation, ...saved.appState.banners?.animation },
      formats: { ...defaults.formats, ...saved.appState.banners?.formats }
    };
    appState.banners.content.label1.style = normalizeBannerChipStyle(appState.banners.content.label1.style);
    appState.banners.content.label2.style = normalizeBannerChipStyle(appState.banners.content.label2.style);

    Object.entries(saved.caseForm || {}).forEach(([id, value]) => {
      const control = document.getElementById(id);
      if (!control) return;
      if (control instanceof HTMLInputElement && (control.type === "checkbox" || control.type === "radio")) {
        control.checked = Boolean(value);
      } else {
        control.value = String(value);
      }
    });
    const background = document.querySelector(`input[name="background"][value="${saved.selectedBackground}"]`);
    if (background instanceof HTMLInputElement) background.checked = true;
    return true;
  } catch (error) {
    console.warn("Не удалось восстановить настройки генератора.", error);
    return false;
  }
}

