const editableOutputToInput = new Map();

function normalizeValue(value) {
  return value.replace(/\r\n/g, "\n").trim();
}

function setOutput(input) {
  const outputId = input.dataset.output;
  if (!outputId) return;

  const output = document.getElementById(outputId);
  if (!output) return;

  output.textContent = normalizeValue(input.value) || "—";
}

function updateCounter(input) {
  const counter = document.querySelector(`[data-counter-for="${input.id}"]`);
  if (!counter || !input.maxLength || input.maxLength < 1) return;

  counter.textContent = `${input.value.length} / ${input.maxLength}`;
}

function getEditableText(output) {
  return output.textContent.replace(/\r\n/g, "\n").trim();
}

function setCaretToEnd(element) {
  const range = document.createRange();
  range.selectNodeContents(element);
  range.collapse(false);

  const selection = window.getSelection();
  if (!selection) return;

  selection.removeAllRanges();
  selection.addRange(range);
}

function getCaretOffset(element) {
  const selection = window.getSelection();
  if (!selection || selection.rangeCount === 0) return 0;

  const range = selection.getRangeAt(0);
  const preCaretRange = range.cloneRange();
  preCaretRange.selectNodeContents(element);
  preCaretRange.setEnd(range.endContainer, range.endOffset);

  return preCaretRange.toString().length;
}

function setCaretByOffset(element, offset) {
  const walker = document.createTreeWalker(element, NodeFilter.SHOW_TEXT);
  let remainingOffset = offset;
  let node = walker.nextNode();

  while (node) {
    const nodeLength = node.textContent.length;

    if (remainingOffset <= nodeLength) {
      const range = document.createRange();
      range.setStart(node, remainingOffset);
      range.collapse(true);

      const selection = window.getSelection();
      if (!selection) return;

      selection.removeAllRanges();
      selection.addRange(range);
      return;
    }

    remainingOffset -= nodeLength;
    node = walker.nextNode();
  }

  setCaretToEnd(element);
}

function insertTextAtSelection(text) {
  const selection = window.getSelection();
  if (!selection || selection.rangeCount === 0) return false;

  const range = selection.getRangeAt(0);
  range.deleteContents();
  range.insertNode(document.createTextNode(text));
  range.collapse(false);

  selection.removeAllRanges();
  selection.addRange(range);
  return true;
}

function enforceEditableLimit(output, input) {
  if (!input.maxLength || input.maxLength < 1) return;

  const text = getEditableText(output);
  if (text.length <= input.maxLength) return;

  output.textContent = text.slice(0, input.maxLength);
  setCaretToEnd(output);
}

function normalizeResultValueOutput(output) {
  if (!output.classList.contains("result-value")) return getEditableText(output);

  return getEditableText(output).replace(/[\r\n]+/g, " ");
}

function syncEditableToInput(output) {
  const input = editableOutputToInput.get(output);
  if (!input) return;

  enforceEditableLimit(output, input);
  input.value = normalizeResultValueOutput(output);
  updateCounter(input);
  updateAdaptiveTypography();
  scheduleAdaptiveTypographyUpdate();
}

function syncEditableOnBlur(output) {
  const input = editableOutputToInput.get(output);
  if (!input) return;

  syncEditableToInput(output);
  setOutput(input);
  updateAdaptiveTypography();
}

function setupInlineEditing() {
  elements.editorForm.querySelectorAll("[data-output]").forEach((input) => {
    const output = document.getElementById(input.dataset.output);
    if (!output) return;

    editableOutputToInput.set(output, input);
    output.contentEditable = "plaintext-only";
    output.spellcheck = false;
    output.tabIndex = 0;
    output.dataset.editableOutput = "";
    output.setAttribute("aria-label", `Редактировать: ${input.closest(".field")?.querySelector(".field__label")?.textContent || "текст"}`);
  });
}

function getEditableOutputFromEvent(event) {
  return event.target instanceof Element
    ? event.target.closest("[data-editable-output]")
    : null;
}

function handleEditableKeydown(event) {
  const output = getEditableOutputFromEvent(event);
  if (!output) return;

  if (event.key === "Escape") {
    event.preventDefault();
    output.blur();
    return;
  }

  if (event.key !== "Enter") return;

  const input = editableOutputToInput.get(output);
  if (!input || output.classList.contains("result-value")) {
    event.preventDefault();
    return;
  }

  event.preventDefault();
  insertTextAtSelection("\n");
  syncEditableToInput(output);
}

function handleEditablePaste(event) {
  const output = getEditableOutputFromEvent(event);
  if (!output) return;

  event.preventDefault();
  const input = editableOutputToInput.get(output);
  const pastedText = event.clipboardData?.getData("text/plain") || "";
  const text = input instanceof HTMLInputElement
    ? pastedText.replace(/[\r\n]+/g, " ")
    : pastedText;

  insertTextAtSelection(text);
  syncEditableToInput(output);
}

function setAdaptiveClass(element, className, enabled) {
  element.classList.toggle(className, enabled);
}

function fitResultValue(valueNode) {
  const length = valueNode.textContent.length;
  const classes = ["is-medium", "is-compact", "is-tiny"];
  valueNode.classList.remove(...classes);
  valueNode.style.removeProperty("font-size");

  valueNode.classList.toggle("is-tiny", length > 16);
  valueNode.classList.toggle("is-medium", length > 7 && length <= 11);
  valueNode.classList.toggle("is-compact", length > 11 && length <= 16);
}

function updateAdaptiveTypography() {
  const summaryLength = elements.summaryOutput.textContent.length;
  elements.summaryOutput.classList.remove("is-medium", "is-compact");

  if (summaryLength > 390) {
    elements.summaryOutput.classList.add("is-compact");
  } else if (summaryLength > 300) {
    elements.summaryOutput.classList.add("is-medium");
  }

  const companyLength = elements.companyOutput.textContent.length;
  elements.companyOutput.classList.remove("is-compact", "is-tiny");
  if (companyLength > 42) {
    elements.companyOutput.classList.add("is-tiny");
  } else if (companyLength > 20) {
    elements.companyOutput.classList.add("is-compact");
  }

  setAdaptiveClass(
    elements.taskOutput,
    "is-compact",
    elements.taskOutput.textContent.length > 150
  );

  const toolText = elements.toolOutput.textContent;
  const toolLineCount = toolText.split(/\r?\n/).length;
  elements.toolOutput.classList.remove("is-compact", "is-tiny");
  if (toolText.length > 50 || toolLineCount > 2) {
    elements.toolOutput.classList.add("is-tiny");
  } else if (toolText.length > 24 || toolLineCount > 1) {
    elements.toolOutput.classList.add("is-compact");
  }

  document.querySelectorAll(".result-value").forEach(fitResultValue);
}

function scheduleAdaptiveTypographyUpdate() {
  window.requestAnimationFrame(updateAdaptiveTypography);
}

function syncFormToSlide() {
  elements.editorForm.querySelectorAll("[data-output]").forEach((input) => {
    setOutput(input);
    updateCounter(input);
    appState.caseCard.fields[input.id] = input.value;
  });

  updateAdaptiveTypography();
}

function syncResultVisibility() {
  const secondEnabled = elements.secondResultToggle.checked;

  elements.secondResultControls.hidden = !secondEnabled;
  elements.secondResultCard.hidden = !secondEnabled;
  elements.thirdResultToggle.disabled = !secondEnabled;

  if (!secondEnabled) {
    elements.thirdResultToggle.checked = false;
  }

  const thirdEnabled = secondEnabled && elements.thirdResultToggle.checked;
  elements.thirdResultControls.hidden = !thirdEnabled;
  elements.thirdResultCard.hidden = !thirdEnabled;

  const visibleCount = 1 + Number(secondEnabled) + Number(thirdEnabled);
  appState.caseCard.secondResultEnabled = secondEnabled;
  appState.caseCard.thirdResultEnabled = thirdEnabled;
  elements.resultsList.classList.remove(
    "results-count-1",
    "results-count-2",
    "results-count-3"
  );
  elements.resultsList.classList.add(`results-count-${visibleCount}`);

  updateAdaptiveTypography();
}

function preloadImage(url) {
  return new Promise((resolve, reject) => {
    const image = new Image();
    image.decoding = "async";
    image.onload = () => resolve(image);
    image.onerror = () => reject(new Error(`Не удалось загрузить фон: ${url}`));
    image.src = url;

    if (image.complete && image.naturalWidth > 0) {
      resolve(image);
    }
  });
}

function getBackgroundUrl(theme, index) {
  const folder = theme === "light" ? "backgrounds-light" : "backgrounds";
  const extension = theme === "light" ? "png" : "webp";
  return `${folder}/prez-bg-${index}.${extension}`;
}

