let bannerFitFrame = 0;
let bannerIsComposing = false;
let bannerDragState = null;
const BANNER_HISTORY_LIMIT = 30;
const bannerHistory = { entries: [], index: -1, timer: 0 };

function getBannerHistorySnapshot() {
  return JSON.stringify(appState.banners);
}

function resetBannerHistory() {
  window.clearTimeout(bannerHistory.timer);
  bannerHistory.entries = [getBannerHistorySnapshot()];
  bannerHistory.index = 0;
}

function commitBannerHistorySnapshot() {
  window.clearTimeout(bannerHistory.timer);
  bannerHistory.timer = 0;
  const snapshot = getBannerHistorySnapshot();
  if (bannerHistory.entries[bannerHistory.index] === snapshot) return;

  bannerHistory.entries.splice(bannerHistory.index + 1);
  bannerHistory.entries.push(snapshot);
  if (bannerHistory.entries.length > BANNER_HISTORY_LIMIT) bannerHistory.entries.shift();
  bannerHistory.index = bannerHistory.entries.length - 1;
}

function queueBannerHistorySnapshot() {
  window.clearTimeout(bannerHistory.timer);
  bannerHistory.timer = window.setTimeout(commitBannerHistorySnapshot, 420);
}

function restoreBannerHistorySnapshot(snapshot) {
  pauseBannerAnimation();
  appState.banners = JSON.parse(snapshot);
  appState.banners.content.label1.style = normalizeBannerChipStyle(appState.banners.content.label1.style);
  appState.banners.content.label2.style = normalizeBannerChipStyle(appState.banners.content.label2.style);
  document.body.dataset.theme = appState.banners.branding.theme;
  syncBannerControls();
  renderBanners();
  applyBannerAnimationFrame(1);
  scheduleProjectSave();
}

function undoBannerChange() {
  commitBannerHistorySnapshot();
  if (bannerHistory.index <= 0) return;
  bannerHistory.index -= 1;
  restoreBannerHistorySnapshot(bannerHistory.entries[bannerHistory.index]);
}

function redoBannerChange() {
  commitBannerHistorySnapshot();
  if (bannerHistory.index >= bannerHistory.entries.length - 1) return;
  bannerHistory.index += 1;
  restoreBannerHistorySnapshot(bannerHistory.entries[bannerHistory.index]);
}

function getValueByPath(root, path) {
  return path.split(".").reduce((value, key) => value?.[key], root);
}

function setValueByPath(root, path, value) {
  const keys = path.split(".");
  const lastKey = keys.pop();
  const target = keys.reduce((result, key) => result[key], root);
  target[lastKey] = value;
}

function syncRangeProgress(input) {
  const minimum = Number(input.min || 0);
  const maximum = Number(input.max || 100);
  const value = Number(input.value);
  const progress = maximum === minimum ? 0 : ((value - minimum) / (maximum - minimum)) * 100;
  input.style.setProperty("--range-progress", `${Math.max(0, Math.min(100, progress))}%`);
}

function syncRangeProgresses(scope = document) {
  scope.querySelectorAll('input[type="range"]').forEach(syncRangeProgress);
}

