bannerElements.form.addEventListener("input", handleBannerControl);
bannerElements.form.addEventListener("change", handleBannerControl);
bannerElements.lightThemeToggle.addEventListener("change", handleBannerControl);
bannerElements.form.addEventListener("click", (event) => {
  const target = event.target instanceof Element ? event.target : null;
  if (!target) return;

  const trigger = target.closest("[data-chip-style-trigger]");
  if (trigger) {
    const select = trigger.closest("[data-chip-style-select]");
    const menu = select?.querySelector("[data-chip-style-menu]");
    if (!select || !menu) return;
    const willOpen = menu.hidden;
    closeChipStyleSelects(select);
    menu.hidden = !willOpen;
    select.classList.toggle("is-open", willOpen);
    trigger.setAttribute("aria-expanded", String(willOpen));
    return;
  }

  const option = target.closest("[data-chip-style-option]");
  if (!option) return;
  const select = option.closest("[data-chip-style-select]");
  const nativeSelect = select?.querySelector("select[data-banner-path]");
  if (!(nativeSelect instanceof HTMLSelectElement) || !option.dataset.value) return;

  nativeSelect.value = option.dataset.value;
  nativeSelect.dispatchEvent(new Event("change", { bubbles: true }));
  closeChipStyleSelects();
});

document.addEventListener("pointerdown", (event) => {
  const target = event.target instanceof Element ? event.target : null;
  if (!target?.closest("[data-chip-style-select]")) closeChipStyleSelects();
});

document.addEventListener("keydown", (event) => {
  if (event.key !== "Escape") return;
  closeChipStyleSelects();
});
document.addEventListener("keydown", (event) => {
  if (!(event.ctrlKey || event.metaKey) || event.altKey) return;
  const target = event.target;
  const isTextEditor = target instanceof HTMLTextAreaElement
    || target instanceof HTMLElement && target.isContentEditable
    || target instanceof HTMLInputElement && !["range", "checkbox", "radio"].includes(target.type);
  if (isTextEditor) return;

  const key = event.key.toLowerCase();
  if (key === "z") {
    event.preventDefault();
    if (event.shiftKey) redoBannerChange();
    else undoBannerChange();
  } else if (key === "y") {
    event.preventDefault();
    redoBannerChange();
  }
});
bannerElements.manualVisualPicker.addEventListener("click", (event) => {
  const option = event.target instanceof Element ? event.target.closest("[data-visual-id]") : null;
  if (!option) return;

  appState.banners.visual.selectedId = option.dataset.visualId;
  appState.banners.visual.mode = "manual";
  syncBannerControls();
  renderBanners();
  commitBannerHistorySnapshot();
  scheduleProjectSave();
});
