bannerElements.canvasHost.addEventListener("focusin", (event) => {
  const node = getBannerEditableFromEvent(event);
  if (!node) return;
  if (node.dataset.bannerEditable === "content.title") {
    node.textContent = appState.banners.content.title;
    node.classList.add("is-editing");
    setCaretToEnd(node);
  }
});

bannerElements.canvasHost.addEventListener("compositionstart", () => {
  bannerIsComposing = true;
});

bannerElements.canvasHost.addEventListener("compositionend", (event) => {
  bannerIsComposing = false;
  const node = getBannerEditableFromEvent(event);
  if (node) syncBannerEditableToState(node);
});

bannerElements.canvasHost.addEventListener("input", (event) => {
  if (bannerIsComposing) return;
  const node = getBannerEditableFromEvent(event);
  if (node) syncBannerEditableToState(node);
});

bannerElements.canvasHost.addEventListener("keydown", (event) => {
  const node = getBannerEditableFromEvent(event);
  if (!node) return;

  if (event.key === "Escape") {
    event.preventDefault();
    node.blur();
    return;
  }

  if (event.key !== "Enter") return;
  event.preventDefault();
  if (node.dataset.multiline === "true") {
    insertBannerPlainText("\n");
    syncBannerEditableToState(node);
  } else {
    node.blur();
  }
});

bannerElements.canvasHost.addEventListener("paste", (event) => {
  const node = getBannerEditableFromEvent(event);
  if (!node) return;
  event.preventDefault();
  let text = event.clipboardData?.getData("text/plain") || "";
  if (node.dataset.multiline !== "true") text = text.replace(/[\r\n]+/g, " ");
  insertBannerPlainText(text);
  syncBannerEditableToState(node);
});

bannerElements.canvasHost.addEventListener("focusout", (event) => {
  const node = getBannerEditableFromEvent(event);
  if (!node) return;
  node.classList.remove("is-editing");
  syncBannerEditableToState(node);
  commitBannerHistorySnapshot();
  renderBanners();
});

bannerElements.canvasHost.addEventListener("pointerdown", (event) => {
  const visual = event.target instanceof Element ? event.target.closest("[data-drag-visual]") : null;
  if (!visual || !appState.banners.visual.enabled) return;
  const canvas = visual.closest(".creative-canvas");
  const format = canvas.dataset.format;
  if (format !== appState.ui.activeBannerFormat) setBannerFormat(format);

  event.preventDefault();
  const rect = canvas.getBoundingClientRect();
  const previewScale = rect.width / BANNER_FORMATS[format].width;
  const formatState = appState.banners.formats[format];
  bannerDragState = {
    pointerId: event.pointerId,
    visual,
    format,
    startClientX: event.clientX,
    startClientY: event.clientY,
    startX: formatState.visualX,
    startY: formatState.visualY,
    previewScale: Math.max(previewScale, 0.01)
  };
  visual.classList.add("is-dragging");
  visual.setPointerCapture(event.pointerId);
});

bannerElements.canvasHost.addEventListener("pointermove", (event) => {
  if (!bannerDragState || event.pointerId !== bannerDragState.pointerId) return;
  const x = bannerDragState.startX + (event.clientX - bannerDragState.startClientX) / bannerDragState.previewScale;
  const y = bannerDragState.startY + (event.clientY - bannerDragState.startClientY) / bannerDragState.previewScale;
  updateDraggedVisual(bannerDragState.format, x, y);
});

function stopBannerDrag(event) {
  if (!bannerDragState || event.pointerId !== bannerDragState.pointerId) return;
  bannerDragState.visual.classList.remove("is-dragging");
  bannerDragState = null;
  commitBannerHistorySnapshot();
}

bannerElements.canvasHost.addEventListener("pointerup", stopBannerDrag);
bannerElements.canvasHost.addEventListener("pointercancel", stopBannerDrag);

bannerElements.canvasHost.addEventListener("click", (event) => {
  const preview = event.target instanceof Element ? event.target.closest(".creative-preview-card") : null;
  if (preview) setBannerFormat(preview.dataset.format);
});

bannerElements.canvasHost.addEventListener("keydown", (event) => {
  if (getBannerEditableFromEvent(event)) return;
  const preview = event.target instanceof Element ? event.target.closest(".creative-preview-card") : null;
  if (!preview || (event.key !== "Enter" && event.key !== " ")) return;
  event.preventDefault();
  setBannerFormat(preview.dataset.format);
});

